SELECT method_group, status, method_list, num_payments FROM (SELECT CASE WHEN method IN ('cash', 'paypal') THEN 'core' ELSE 'other' END AS method_group, status, SORT_ARRAY(COLLECT_SET(method)) AS method_list, COUNT(*) AS num_payments FROM payments WHERE method IN ('paypal', 'promptpay', 'bank_transfer') GROUP BY CASE WHEN method IN ('cash', 'paypal') THEN 'core' ELSE 'other' END, status) AS sub WHERE num_payments < 7 ORDER BY num_payments;
